import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    assign_re = re.compile(r'^\s*([A-Za-z_][A-Za-z_0-9]*)\s*<-\s*(.+?)\s*;?\s*$')

    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        # Strip trailing inline comments, if any
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        m = assign_re.match(line)
        if not m:
            continue
        target, expr = m.group(1), m.group(2).strip().rstrip(';').strip()
        if re.fullmatch(r'-?\d+', expr):
            val = int(expr)
        elif re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]*', expr):
            val = env.get(expr, 0)
        else:
            # Fallback: evaluate simple arithmetic with variables
            def repl(mm):
                return str(env.get(mm.group(0), 0))
            safe = re.sub(r'[A-Za-z_][A-Za-z_0-9]*', repl, expr)
            try:
                val = eval(safe, {"__builtins__": {}}, {})
            except Exception:
                continue
        env[target] = val

    names = list("abcdefghijklmnop") + ["TMP"]
    out = " ".join(f"{n} ?= {env.get(n, 0)};" for n in names)
    print(out)

if __name__ == "__main__":
    main()
